class Solution {
  public boolean canPartitionGrid(int[][] grid) {
    int m = grid.length, n = grid[0].length;
    long[] rows = new long[m], cols = new long[n];
    long total = 0;
    for (int i = 0; i < m; i++) {
      for (int j = 0; j < n; j++) {
        rows[i] += grid[i][j];
        cols[j] += grid[i][j];
        total += grid[i][j];
      }
    }
    if (total % 2 != 0) return false;
    long prefix = 0;
    for (int i = 0; i + 1 < m; i++) {
      prefix += rows[i];
      if (prefix * 2 == total) return true;
    }
    prefix = 0;
    for (int j = 0; j + 1 < n; j++) {
      prefix += cols[j];
      if (prefix * 2 == total) return true;
    }
    return false;
  }
}
